package complexity_test

import (
	"fmt"
	"os"
	"slices"
	"strings"
	"testing"

	"github.com/Hedronite/go-tops/internal/complexity"
)

// Parity with gocyclo (GO_TOPS.md §6.3, "Baseline (matches gocyclo)"). With the
// discount off the figures equal gocyclo's on the corpus in testdata/corpus.
// gocyclo's output is committed as testdata/gocyclo.golden and regenerated by
// scripts/goldens/gocyclo.sh, which runs gocyclo from tools/go.mod only.
//
// Golden lines read `<complexity> <package> <function> <file:line:column>`,
// where <function> is `Name` or `(Recv).Name` / `(*Recv).Name`.

func goldenLine(f complexity.Func) string {
	name := f.Name
	if f.Recv != "" {
		name = "(" + f.Recv + ")." + f.Name
	}
	return fmt.Sprintf("%d %s %s %s:%d:%d", f.Complexity, f.PkgName, name, f.File, f.Span.Start.Line, f.Span.Start.Col)
}

func readGolden(t *testing.T) []string {
	t.Helper()
	raw, err := os.ReadFile("testdata/gocyclo.golden")
	if err != nil {
		t.Fatal(err)
	}
	var lines []string
	for line := range strings.SplitSeq(strings.TrimSpace(string(raw)), "\n") {
		// gocyclo writes the receiver of a pointer method as `(*T)`; the
		// pointer is a property of the declaration, not of the key.
		lines = append(lines, strings.Replace(line, "(*", "(", 1))
	}
	slices.Sort(lines)
	return lines
}

func TestParityWithGocycloGoldens(t *testing.T) {
	pkgs, err := complexity.Load("testdata/corpus", nil, "./...")
	if err != nil {
		t.Fatal(err)
	}
	funcs, err := complexity.Analyze("testdata/corpus", pkgs, complexity.Config{})
	if err != nil {
		t.Fatal(err)
	}
	var got []string
	for _, f := range funcs {
		got = append(got, goldenLine(f))
	}
	slices.Sort(got)
	want := readGolden(t)
	if !slices.Equal(got, want) {
		t.Errorf("complexity differs from the gocyclo goldens\n got:\n%s\nwant:\n%s",
			strings.Join(got, "\n"), strings.Join(want, "\n"))
	}
}

// The corpus is only a parity check if it holds what the oracle is about: the
// golden must pin the figures the comments in the corpus derive from §6.3.
func TestCorpusFigures(t *testing.T) {
	want := map[string]int{
		"Straight": 1, "Branches": 4, "SwitchDefault": 4, "TypeSwitch": 3, "Loops": 5,
		"Logic": 5, "Closure": 5, "Guards": 4, "Goto": 3, "Lit": 2, "A": 1, "B": 2,
		"Shadow": 2, "Map": 3, "Sum": 2, "Pump": 5, "Fan": 4,
	}
	pkgs, err := complexity.Load("testdata/corpus", nil, "./...")
	if err != nil {
		t.Fatal(err)
	}
	funcs, err := complexity.Analyze("testdata/corpus", pkgs, complexity.Config{})
	if err != nil {
		t.Fatal(err)
	}
	got := map[string]int{}
	for _, f := range funcs {
		if f.Recv == "" {
			got[f.Name] = f.Complexity
		}
	}
	for name, c := range want {
		if got[name] != c {
			t.Errorf("%s: complexity %d, want %d", name, got[name], c)
		}
	}
}
